function 쿠폰만료(쿠폰) {
  return new Date() > new Date(쿠폰.끝);   // 오늘이 언제냐에 따라 결과가 바뀐다
}

// 테스트를 쓰면 내년에 갑자기 빨개진다

function 쿠폰만료(쿠폰, 지금 = new Date()) {
  return 지금 > new Date(쿠폰.끝);
}

test('만료일 다음날이면 만료다', () => {
  const 쿠폰 = { 끝: '2026-01-10' };
  expect(쿠폰만료(쿠폰, new Date('2026-01-11'))).toBe(true);
  expect(쿠폰만료(쿠폰, new Date('2026-01-09'))).toBe(false);
});
